15	class DigitalHubTableMacro
16	{
17	    public static function register(): void
18	    {
19	        // register a macro to perform some customization on all tables of the Digital Hub, like adding a default record action to open the edit page
20	        Table::macro('digitalHubTable', function (array $recordActions = []): Table {
21	            // $this is bound to the Table instance at runtime by Laravel's Macroable;
22	            // PHPStan cannot infer this statically for a macro closure.
23	            /** @var Table $this */
24	            // @phpstan-ignore-next-line varTag.variableNotFound, variable.undefined, argument.type
25	            return DigitalHubTableMacro::apply($this, $recordActions);
26	        });
27	    }
28	
29	    /**
30	     * Apply the Digital Hub customizations to a table.
31	     *
32	     * @param array<\Filament\Actions\Action> $recordActions Azioni di riga extra,
33	     *                                                       anteposte all'ActionGroup standard (es. ManageAssetsAction).
34	     */
35	    public static function apply(Table $table, array $recordActions = []): Table
36	    {
37	        $table->recordActions([
38	            ...$recordActions,
39	            ActionGroup::make([
40	                EditAction::make()->slideOver()->modalWidth(Width::SevenExtraLarge),
41	                DeleteAction::make(),
42	            ]),
43	        ])
44	        ->toolbarActions([
45	            BulkActionGroup::make([
46	                DeleteBulkAction::make()
47	                    ->modalHeading(__('digital-hub::common.delete_confirmation')),
48	            ]),
49	        ])
50	        ->defaultSort('sort')
51	        ->reorderable('sort')
52	        ;
53	
54	        // customize filters
55	        $filters = $table->getFilters();
56	        if (count($filters) > 2) {
57	            $table->filtersFormColumns(3);
58	        }
59	
60	        // $table->filters($filters,);
61	
62	
63	        // convert the created_at column to proper timezone and format if it exists
64	        collect($table->getColumns())->each(function (Column $column): void {
65	            if ($column instanceof TextColumn && $column->getName() === 'created_at') {
66	                $column->dateTime('d/m/Y H:i', 'Europe/Rome')->sortable()->toggleable(isToggledHiddenByDefault: true);
67	            }
68	        });
69	
70	        return $table;
71	    }
72	}
